import requests
qs=['"retractor" sacrum "Stoppa" L5 acetabular','"retractor on the sacrum" pelvic fracture','"sacral ala" retractor "L5" Stoppa','combined acetabular pelvic ring surgery Stoppa lateral window retractor sacrum']
for q in qs:
 r=requests.get('https://eutils.ncbi.nlm.nih.gov/entrez/eutils/esearch.fcgi',params={'db':'pubmed','term':q,'retmode':'json','retmax':8},timeout=20)
 ids=r.json().get('esearchresult',{}).get('idlist',[])
 print('\nQUERY',q,'PMIDs',ids)
 if ids:
  s=requests.get('https://eutils.ncbi.nlm.nih.gov/entrez/eutils/esummary.fcgi',params={'db':'pubmed','id':','.join(ids),'retmode':'json'},timeout=20).json().get('result',{})
  for i in ids: print(i,s.get(i,{}).get('title'))

import requests
qs=['"Stoppa" "retractor" sacrum acetabular','"L5 nerve root" retractor sacrum pelvic','"sacral ala" "retractor" acetabular fracture']
for q in qs:
 d=requests.get('https://www.ebi.ac.uk/europepmc/webservices/rest/search',params={'query':q,'format':'json','pageSize':6,'resultType':'core'},timeout=25).json()
 print('\nQUERY',q,'count',d.get('hitCount'))
 for x in d.get('resultList',{}).get('result',[]): print(x.get('pmid'),x.get('title'),x.get('authorString'),x.get('doi'))
